import React, { useRef, useState } from 'react';
import styles from './PhoneInput.module.css';

const PhoneInput = ({ label, value, onChange, error, ...props }) => {
    const inputRef = useRef(null);
    const [isFocused, setIsFocused] = useState(false);

    const getDigitsOnly = (str) => {
        return str.replace(/\D/g, '');
    };

    const formatPhoneNumber = (digits) => {
        if (!digits) return '';

        let number = digits;
        if (number.startsWith('375')) {
            number = number.slice(3);
        }

        number = number.slice(0, 9);

        if (number.length === 0) return '+375';

        let result = '+375';

        if (number.length > 0) {
            result += ' ' + number.slice(0, 2);
        }
        if (number.length > 2) {
            result += ' ' + number.slice(2, 5);
        }
        if (number.length > 5) {
            result += '-' + number.slice(5, 7);
        }
        if (number.length > 7) {
            result += '-' + number.slice(7, 9);
        }

        return result;
    };

    const getNewCaretPosition = (oldValue, newValue, oldCaretPos) => {
        const oldDigits = getDigitsOnly(oldValue);
        const newDigits = getDigitsOnly(newValue);

        if (newDigits.length < oldDigits.length) {
            let count = 0;
            for (let i = 0; i < newValue.length; i++) {
                if (/\d/.test(newValue[i])) {
                    if (count === newDigits.length) {
                        return i;
                    }
                    count++;
                }
            }
            return newValue.length;
        }

        if (newDigits.length > oldDigits.length) {
            let count = 0;
            for (let i = 0; i < newValue.length; i++) {
                if (/\d/.test(newValue[i])) {
                    if (count === newDigits.length) {
                        return i + 1;
                    }
                    count++;
                }
            }
            return newValue.length;
        }

        return oldCaretPos;
    };

    const handleChange = (e) => {
        const rawValue = e.target.value;
        const oldValue = value || '';
        const oldCaretPos = inputRef.current?.selectionStart || 0;

        const digits = getDigitsOnly(rawValue);
        const formatted = formatPhoneNumber(digits);
        const newCaretPos = getNewCaretPosition(oldValue, formatted, oldCaretPos);

        onChange({ target: { value: formatted } });

        setTimeout(() => {
            if (inputRef.current) {
                inputRef.current.setSelectionRange(newCaretPos, newCaretPos);
            }
        }, 0);
    };

    const handleKeyDown = (e) => {
        if (e.key === 'Backspace') {
            const currentValue = value || '';
            const cursorPos = inputRef.current?.selectionStart || 0;

            let digitsBeforeCursor = 0;
            for (let i = 0; i < cursorPos && i < currentValue.length; i++) {
                if (/\d/.test(currentValue[i])) {
                    digitsBeforeCursor++;
                }
            }

            const totalDigits = getDigitsOnly(currentValue).length;

            if (digitsBeforeCursor === 0 && totalDigits === 0) {
                e.preventDefault();
                return;
            }

            if (totalDigits === 0) {
                e.preventDefault();
                return;
            }
        }

        if (e.key.length === 1 && !/[0-9]/.test(e.key)) {
            e.preventDefault();
        }
    };

    const handlePaste = (e) => {
        e.preventDefault();
        const pastedText = e.clipboardData.getData('text');
        const digits = getDigitsOnly(pastedText);

        if (digits) {
            const formatted = formatPhoneNumber(digits);
            onChange({ target: { value: formatted } });

            setTimeout(() => {
                if (inputRef.current) {
                    inputRef.current.setSelectionRange(formatted.length, formatted.length);
                }
            }, 0);
        }
    };

    const handleFocus = () => {
        setIsFocused(true);
        if (!value) {
            onChange({ target: { value: '+375 ' } });
            setTimeout(() => {
                if (inputRef.current) {
                    inputRef.current.setSelectionRange(5, 5);
                }
            }, 0);
        }
    };

    const handleBlur = () => {
        setIsFocused(false);
        const digits = getDigitsOnly(value || '');
        if (digits.length < 12) {
            onChange({ target: { value: '' } });
        }
    };

    const displayValue = value || (isFocused ? '+375 ' : '');

    return (
        <div className={styles.phoneGroup}>
            {label && <label className={styles.label}>{label}</label>}
            <div className={styles.phoneWrapper}>
                <input
                    ref={inputRef}
                    type="tel"
                    className={`${styles.phoneInput} ${error ? styles.error : ''}`}
                    value={displayValue}
                    onChange={handleChange}
                    onKeyDown={handleKeyDown}
                    onPaste={handlePaste}
                    onFocus={handleFocus}
                    onBlur={handleBlur}
                    placeholder="+375 00 000-00-00"
                    {...props}
                />
            </div>
            {error && <span className={styles.errorMessage}>{error}</span>}
        </div>
    );
};

export default PhoneInput;
